use std::path::Path;

use editor_core::{ChangedEntity, JobId, Project, ProjectRevision, RequestId};
use job_system::{JobFailure, JobKind, JobSnapshot, JobState};
use project_io::{RecoveryCandidate, RecoverySnapshot};
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ProjectSnapshotDto {
    pub revision: ProjectRevision,
    pub project: Project,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct CommandResultDto {
    pub request_id: RequestId,
    pub revision: ProjectRevision,
    pub changed_entities: Vec<ChangedEntity>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RecoveryCandidateDto {
    pub path: String,
    pub revision: ProjectRevision,
    pub created_at_ms: u64,
}

impl From<RecoveryCandidate> for RecoveryCandidateDto {
    fn from(candidate: RecoveryCandidate) -> Self {
        Self {
            path: candidate.path.to_string_lossy().into_owned(),
            revision: candidate.revision,
            created_at_ms: candidate.created_at_ms,
        }
    }
}

impl From<RecoverySnapshot> for RecoveryCandidateDto {
    fn from(snapshot: RecoverySnapshot) -> Self {
        Self {
            path: snapshot.path.to_string_lossy().into_owned(),
            revision: snapshot.revision,
            created_at_ms: snapshot.created_at_ms,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct JobEventDto {
    pub job_id: JobId,
    pub kind: JobKind,
    pub state: JobState,
    pub progress: f32,
    pub source_revision: ProjectRevision,
    pub failure: Option<JobFailure>,
}

impl From<JobSnapshot> for JobEventDto {
    fn from(snapshot: JobSnapshot) -> Self {
        Self {
            job_id: snapshot.context.job_id,
            kind: snapshot.kind,
            state: snapshot.state,
            progress: snapshot.progress,
            source_revision: snapshot.context.source_revision,
            failure: snapshot.failure,
        }
    }
}

