pub fn write_typescript_contract(path: &Path) -> std::io::Result<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, TYPESCRIPT_CONTRACTS.as_bytes())
}
